const existing = $('Fetch Existing Stories').all().map(x => x.json.Title).filter(Boolean);
let runOpts = {};
try {
  const first = $input.first();
  if (first && first.binary && first.binary.data) {
    const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
    runOpts = JSON.parse(buf.toString('utf8')) || {};
  }
} catch {}
const customSubject = String(runOpts.subject || '').trim();
const subTheme = String(runOpts.subTheme || '').trim();
const recent = existing.slice(-5);
const avoid = existing.length ? 'Do NOT repeat or closely overlap any of these existing stories: ' + existing.join('; ') + '.' : 'No existing stories yet.';
const rotationHint = customSubject
  ? `USER-REQUESTED SUBJECT: Candidate #1 MUST be "${customSubject}" (researched accurately from historical/museum/archive sources). Propose 2 other distinct backup subjects.`
  : subTheme
    ? `USER-REQUESTED SUB-THEME: Candidate #1 MUST belong to the sub-theme "${subTheme}". Propose 2 other distinct subjects from other sub-themes.`
    : (recent.length ? `SUB-THEME ROTATION: Recent stories were [${recent.join('; ')}]. For Candidate #1 (priority 1), deliberately pick a DIFFERENT sub-theme and era from those recent stories (e.g., if recent stories were physical craft/ships/furniture, pick Digital Interfaces & Information Design, Architecture & Infrastructure, or Scientific Instruments & Mapping).` : 'Rotate across all 4 sub-themes.');
const prompt = [
  'You are the editorial researcher for WE, HUMANITY, a series about human creativity, discovery, craftsmanship, and design across both physical artifacts and digital/information systems.',
  'Propose THREE distinct, specific, real, historically documented subjects from different eras and regions, rotating across these 4 sub-themes: (1) Physical Craft & Vessels (tools, watercraft, everyday/industrial design classics), (2) Architecture & Infrastructure (water systems, bridges, passive cooling, survival structures), (3) Scientific Instruments & Mapping (chronometers, star charts, navigation tools), and (4) Digital Interfaces & Information Design (iconic graphical interfaces, typography, wayfinding maps, or early computing hardware/UI breakthroughs). Choose subjects that are well-documented in museum or computing archives and likely to have freely licensed photographs or specimens on Wikimedia Commons or Openverse.',
  rotationHint,
  avoid,
  'Set pillar to "Form and function" for every item.',
  'Return ONLY JSON: {"candidates":[{"title":"...","pillar":"Form and function","brief":"2-3 factual sentences summarizing the hard constraint it solved, who made it, when, and the exact mechanism or interface decision that made it work","priority":1}]}'
].join('\n\n');
return [{ json: { prompt, hasOverride: Boolean(customSubject || subTheme) } }];

const existingTitles = $('Fetch Existing Stories').all().map(x => String(x.json.Title || '').toLowerCase()).filter(Boolean);
const hasOverride = Boolean($('Build Discovery Prompt').first().json.hasOverride);
const words = s => new Set(String(s || '').toLowerCase().split(/[^a-z0-9]+/).filter(w => w.length >= 3));
const isDuplicate = (title) => {
  const t = String(title || '').toLowerCase().trim();
  if (!t) return true;
  if (existingTitles.some(e => e === t || e.includes(t) || t.includes(e))) return true;
  const tw = words(t);
  for (const e of existingTitles) {
    const ew = words(e);
    const overlap = [...tw].filter(w => ew.has(w)).length;
    if (tw.size > 0 && overlap / Math.min(tw.size, ew.size || 1) >= 0.6) return true;
  }
  return false;
};
const item = $json;
let d;
if (item.candidates || item.title) {
  d = item;
} else {
  const parts = item?.content?.parts ?? item?.candidates?.[0]?.content?.parts ?? [];
  let raw = parts.map(p => p.text || '').join('') || item.text || item.output || '';
  raw = raw.replace(/```json|```/g, '').trim();
  d = JSON.parse(raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1));
}
const list = Array.isArray(d.candidates) ? d.candidates : [d];
const picked = list.find(c => c && c.title && c.brief && !isDuplicate(c.title));
if (!picked) throw new Error('WF1 could not find a non-duplicate story subject');
return [{ json: { Title: picked.title, Pillar: ['Form and function'].includes(picked.pillar) ? picked.pillar : 'Form and function', Brief: picked.brief, Status: 'queued', Priority: hasOverride ? 0 : (Number(picked.priority) || 1) } }];
